SELECT analytics_expense_facts.expense_category, SUM(analytics_expense_facts.expense_amount) AS expense_amount FROM analytics_expense_facts WHERE analytics_expense_facts.year = 2026 AND analytics_expense_facts.month = 9 AND analytics_expense_facts.department = 'department_15' AND analytics_expense_facts.cost_center = 'cc_045' GROUP BY analytics_expense_facts.expense_category ORDER BY expense_amount DESC, analytics_expense_facts.expense_category ASC LIMIT 15
